/* ========================================
   Volta Studio — Shared Design System
   ======================================== */

/* --- Custom Properties --- */
:root {
  --color-bg: #F5F2ED;
  --color-text: #1A1A1A;
  --color-text-muted: #6B6560;
  --color-terracotta: #C4725A;
  --color-sage: #8B9E82;
  --color-sand: #D4C5A9;
  --color-slate: #9B9E9B;
  --color-cream-dark: #E8E3DB;
  --color-border: #D8D3CB;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* --- Typography --- */
.font-serif {
  font-family: var(--font-serif);
}

.font-sans {
  font-family: var(--font-sans);
}

.text-muted {
  color: var(--color-text-muted);
}

/* --- Header --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--color-bg);
  transition: background 0.3s ease;
}

.site-logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-desktop {
  display: flex;
  gap: 2.5rem;
  align-items: center;
}

.nav-desktop a {
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 500;
  transition: opacity 0.3s ease;
}

.nav-desktop a:hover {
  opacity: 0.5;
}

.nav-desktop a.active {
  opacity: 0.4;
}

/* --- Mobile Menu --- */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  padding: 4px;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--color-text);
  transition: all 0.4s cubic-bezier(0.76, 0, 0.24, 1);
  transform-origin: center;
}

.hamburger.is-open span:nth-child(1) {
  transform: rotate(45deg) translate(4.5px, 4.5px);
}

.hamburger.is-open span:nth-child(2) {
  opacity: 0;
}

.hamburger.is-open span:nth-child(3) {
  transform: rotate(-45deg) translate(4.5px, -4.5px);
}

.mobile-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s cubic-bezier(0.76, 0, 0.24, 1);
}

.mobile-overlay.is-open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 400;
  transition: opacity 0.3s ease;
}

.mobile-overlay a:hover {
  opacity: 0.5;
}

/* --- Sections --- */
.section {
  padding: 6rem 2.5rem;
}

.section-wide {
  padding: 6rem 0;
}

.container-narrow {
  max-width: 720px;
  margin: 0 auto;
}

.container-medium {
  max-width: 1000px;
  margin: 0 auto;
}

.container-wide {
  max-width: 1200px;
  margin: 0 auto;
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 2.5rem 4rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 900px;
}

/* --- Media Showcase --- */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 0.75rem;
  padding: 0 2.5rem;
  margin-top: 4rem;
}

.media-block {
  aspect-ratio: 4 / 5;
  width: 100%;
}

.media-block-1 {
  background-color: var(--color-terracotta);
}

.media-block-2 {
  background-color: var(--color-sage);
}

.media-block-3 {
  background-color: var(--color-sand);
}

/* --- Client Marquee --- */
.marquee-section {
  padding: 5rem 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  width: max-content;
  will-change: transform;
}

.marquee-row.row-1 {
  animation: marquee-left 40s linear infinite;
}

.marquee-row.row-2 {
  animation: marquee-right 45s linear infinite;
}

.marquee-row.row-3 {
  animation: marquee-left 38s linear infinite;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 400;
  white-space: nowrap;
  padding: 0 2rem;
  letter-spacing: -0.01em;
}

.marquee-item .dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-text-muted);
  margin: 0 2rem;
  vertical-align: middle;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* --- About --- */
.about-label {
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: 2rem;
}

.about-text {
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.75;
  max-width: 680px;
}

.about-text p + p {
  margin-top: 1.5rem;
}

/* --- Founder Letter --- */
.letter-header {
  padding-top: 12rem;
  padding-bottom: 2rem;
}

.letter-body {
  font-size: clamp(1.05rem, 1.4vw, 1.15rem);
  line-height: 1.85;
  color: var(--color-text);
}

.letter-body p + p {
  margin-top: 1.8rem;
}

.letter-body .sign-off {
  margin-top: 3rem;
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-style: italic;
}

/* --- Philosophy --- */
.philosophy-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.philosophy-text {
  font-size: clamp(1rem, 1.4vw, 1.1rem);
  line-height: 1.8;
  max-width: 600px;
  margin-top: 2rem;
}

/* --- Divider --- */
.divider {
  width: 60px;
  height: 1px;
  background: var(--color-border);
  margin: 4rem 0;
}

/* --- Service Details --- */
.services-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 400;
  line-height: 1.3;
  margin-bottom: 4rem;
  max-width: 700px;
}

.service-item {
  margin-bottom: 3.5rem;
}

.service-name {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.service-desc {
  font-size: 0.95rem;
  line-height: 1.75;
  color: var(--color-text-muted);
  max-width: 560px;
}

/* --- Clients Grid --- */
.clients-heading {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 3.5rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.6rem;
}

.client-card p {
  font-size: 0.85rem;
  line-height: 1.65;
  color: var(--color-text-muted);
}

/* --- Contact --- */
.contact-hero {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding: 0 2.5rem;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 14rem);
  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 0.9;
}

.contact-links {
  margin-top: 3rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.contact-links a {
  font-size: 1rem;
  letter-spacing: 0.04em;
  transition: opacity 0.3s ease;
}

.contact-links a:hover {
  opacity: 0.5;
}

/* --- Footer --- */
.site-footer {
  padding: 3rem 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  color: var(--color-text-muted);
  border-top: 1px solid var(--color-border);
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .site-header {
    padding: 1.25rem 1.5rem;
  }

  .nav-desktop {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 0 1.5rem 3rem;
  }

  .hero-title {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    padding: 0 1.5rem;
    gap: 0.5rem;
    margin-top: 3rem;
  }

  .media-block {
    aspect-ratio: 16 / 9;
  }

  .section {
    padding: 4rem 1.5rem;
  }

  .marquee-item {
    font-size: clamp(1.5rem, 5vw, 2rem);
    padding: 0 1.25rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-title {
    font-size: clamp(4rem, 20vw, 8rem);
  }

  .site-footer {
    padding: 2rem 1.5rem;
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

