  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 0.9;
}

.contact-links {
  margin-top: 3rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.contact-links a {
  font-size: 1rem;
  letter-spacing: 0.04em;
  transition: opacity 0.3s ease;
}

.contact-links a:hover {
  opacity: 0.5;
}

